    function saveDemoState(state) {
      try {
        sessionStorage.setItem(MOCK_STORAGE_KEY, JSON.stringify(state));
      } catch(e) {}
    }
    function applyStats(s) {
      document.getElementById('kpiOccupancy').textContent = s.occupancy_pct + '%';
      document.getElementById('kpiOccupiedCount').textContent = s.occupied_count;
      document.getElementById('kpiCheckins').textContent = s.checkins_today;
      document.getElementById('kpiCheckouts').textContent = s.checkouts_today;
      document.getElementById('kpiRevenue').textContent = '₹' + Math.round(s.total_revenue).toLocaleString('en-IN');
      document.getElementById('kpiActiveTickets').textContent = (s.active_orders || 0) + (s.pending_concierge || 0);
      document.getElementById('kpiActiveKot').textContent = s.active_orders || 0;
      document.getElementById('kpiActiveConcierge').textContent = s.pending_concierge || 0;
      document.getElementById('dashAvailCount').textContent = s.available_count;
      document.getElementById('dashOccCount').textContent = s.occupied_count;
      document.getElementById('dashResCount').textContent = s.reserved_count;
      document.getElementById('dashDirtyCount').textContent = s.dirty_count;
      document.getElementById('dashMaintCount').textContent = s.maintenance_count;
      document.getElementById('availRoomBadge').textContent = s.available_count;
      document.getElementById('activeKotBadge').textContent = s.active_orders || 0;
      document.getElementById('pendingConciergeBadge').textContent = s.pending_concierge || 0;
    }
    async function fetchStats() {
      try {
        const res = await fetch('/api/stats');
        if (res.ok) {
          const data = await res.json();
          if (data.success) {
            applyStats(data.stats);
            return;
          }
        }
        throw new Error('Fallback to demo stats');
      } catch (err) {
        const state = getDemoState();
        applyStats(state.stats);
      }
    }
    async function loadRooms() {
      try {
        const res = await fetch('/api/rooms');
        if (res.ok) {
          const data = await res.json();
          if (data.success) {
            currentRooms = data.rooms;
            renderRooms(currentRooms);
            return;
          }
        }
        throw new Error('Fallback to demo rooms');
      } catch (err) {
        const state = getDemoState();
        currentRooms = state.rooms;
        renderRooms(currentRooms);
      }
    }
    function renderRooms(roomsToRender) {
      const container = document.getElementById('roomMatrixGrid');
      container.innerHTML = '';
      roomsToRender.forEach(r => {
        const card = document.createElement('div');
        card.className = `room-card status-${r.status}`;
        let statusText = 'Available';
        let badgeClass = 'badge-available';
        if (r.status === 'occupied') { statusText = 'Occupied'; badgeClass = 'badge-occupied'; }
        else if (r.status === 'reserved') { statusText = 'Reserved'; badgeClass = 'badge-reserved'; }
        else if (r.status === 'dirty') { statusText = 'Needs Cleaning'; badgeClass = 'badge-dirty'; }
        else if (r.status === 'maintenance') { statusText = 'Maintenance'; badgeClass = 'badge-maintenance'; }
        card.innerHTML = `
          <div>
            <div class="room-card-header">
              <div class="room-number-box">
                <span class="room-number">${r.room_number}</span>
                <span class="room-floor">Floor ${r.floor}</span>
              </div>
              <span class="status-badge ${badgeClass}">${statusText}</span>
            </div>
            <div class="room-type-tag">${r.type_name}</div>
          </div>
          <div class="room-card-body">
            ${r.assigned_guest ? `<div class="room-guest-name">👤 ${r.assigned_guest}</div>` : ''}
            ${r.cleaning_notes ? `<div class="room-notes">📋 ${r.cleaning_notes}</div>` : '<div class="room-notes">No active notes</div>'}
          </div>
          <div class="room-card-actions">
            <button class="btn-room-status" onclick="openRoomStatusModal('${r.room_number}', '${r.status}', '${(r.cleaning_notes || '').replace(/'/g, "\\'")}')">Update Status ▾</button>
          </div>
        `;
        container.appendChild(card);
      });
    }
    function filterRooms(filter, btn) {
      document.querySelectorAll('#roomFilterPills .filter-pill').forEach(p => p.classList.remove('active'));
      if (btn) btn.classList.add('active');
      if (filter === 'all') {
        renderRooms(currentRooms);
      } else if (filter === 'floor1') {
        renderRooms(currentRooms.filter(r => r.floor === 1));
      } else if (filter === 'floor2') {
        renderRooms(currentRooms.filter(r => r.floor === 2));
      } else {
        renderRooms(currentRooms.filter(r => r.status === filter));
      }
    }
    function openRoomStatusModal(roomNum, status, note) {
      selectedRoomForModal = roomNum;
      document.getElementById('modalRoomNum').textContent = roomNum;
      document.getElementById('modalRoomStatusSelect').value = status;
      document.getElementById('modalRoomNote').value = note || '';
      openModal('roomStatusModal');
    }
    async function saveRoomStatus() {
      if (!selectedRoomForModal) return;
      const status = document.getElementById('modalRoomStatusSelect').value;
      const cleaning_notes = document.getElementById('modalRoomNote').value;
      try {
        const res = await fetch(`/api/rooms/${selectedRoomForModal}/status`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ status, cleaning_notes })
        });
        if (res.ok) {
          const data = await res.json();
          if (data.success) {
            closeModal('roomStatusModal');
            loadRooms();
            fetchStats();
            addActivityItem(`Room ${selectedRoomForModal} marked as ${status.toUpperCase()}`);
            return;
          }
        }
        throw new Error('API fallback');
      } catch (err) {
        const state = getDemoState();
        const rm = state.rooms.find(r => r.room_number === selectedRoomForModal);
        if (rm) {
          rm.status = status;
          rm.cleaning_notes = cleaning_notes;
          state.stats.occupied_count = state.rooms.filter(r => r.status === 'occupied').length;
          state.stats.available_count = state.rooms.filter(r => r.status === 'available').length;
          state.stats.reserved_count = state.rooms.filter(r => r.status === 'reserved').length;
          state.stats.dirty_count = state.rooms.filter(r => r.status === 'dirty').length;
          state.stats.maintenance_count = state.rooms.filter(r => r.status === 'maintenance').length;
          state.stats.occupancy_pct = +(state.stats.occupied_count / state.rooms.length * 100).toFixed(1);
          saveDemoState(state);
          currentRooms = state.rooms;
          renderRooms(currentRooms);
          applyStats(state.stats);
          closeModal('roomStatusModal');
          addActivityItem(`Room ${selectedRoomForModal} marked as ${status.toUpperCase()}`);
        }
      }
    }
    function openPriceModal() {
      openModal('priceModal');
    }
    async function saveRoomPrices() {
      const pDeluxe = document.getElementById('priceDeluxe').value;
      const pGarden = document.getElementById('priceGarden').value;
      const pSuite = document.getElementById('priceSuite').value;
      const pExec = document.getElementById('priceExecutive').value;
      try {
        await fetch('/api/room-types/deluxe/price', { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ price: pDeluxe }) });
        await fetch('/api/room-types/garden/price', { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ price: pGarden }) });
        await fetch('/api/room-types/suite/price', { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ price: pSuite }) });
        await fetch('/api/room-types/executive/price', { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ price: pExec }) });
        closeModal('priceModal');
        alert('Room rates successfully updated and live on website!');
      } catch (err) {
        closeModal('priceModal');
        alert('Room rates successfully updated (Demo Mode)!');
      }
    }
    async function loadBookings() {
      const filter = document.getElementById('bookingStatusFilter').value;
      try {
        const res = await fetch(`/api/bookings?status=${filter}`);
        if (res.ok) {
          const data = await res.json();
          if (data.success) {
            currentBookings = data.bookings;
            renderBookings(currentBookings);
            return;
          }
        }
        throw new Error('API fallback');
      } catch (err) {
        const state = getDemoState();
        currentBookings = filter === 'all' 
          ? state.bookings 
          : state.bookings.filter(b => b.booking_status === filter);
        renderBookings(currentBookings);
      }
    }
    function renderBookings(bookings) {
      const filtered = getFilteredBookings();
      renderBookingsSlice(filtered);
    }
    function renderBookingsSlice(bookings) {
      const tbody = document.getElementById('bookingsTableBody');
      const total = bookings.length;
      const maxPages = Math.max(1, Math.ceil(total / bookingPageSize));
      if (bookingCurrentPage > maxPages) bookingCurrentPage = maxPages;
      const start = (bookingCurrentPage - 1) * bookingPageSize;
      const end = start + bookingPageSize;
      const pageSlice = bookings.slice(start, end);
      const sliceSignature = JSON.stringify(pageSlice.map(b => [b.id, b.status, b.booking_status, b.assigned_room_number, b.room_number]));
      if (_lastRendered.bookings === sliceSignature && tbody.children.length > 0) {
        return;
      }
      _lastRendered.bookings = sliceSignature;
      tbody.innerHTML = '';
      const pageInfo = document.getElementById('paginationInfo');
      const pageDisp = document.getElementById('currentPageDisplay');
      const prevBtn = document.getElementById('btnPrevPage');
      const nextBtn = document.getElementById('btnNextPage');
      if (pageInfo) pageInfo.textContent = `Showing ${total ? start + 1 : 0} to ${Math.min(end, total)} of ${total} bookings`;
      if (pageDisp) pageDisp.textContent = `Page ${bookingCurrentPage} of ${maxPages}`;
      if (prevBtn) prevBtn.disabled = (bookingCurrentPage <= 1);
      if (nextBtn) nextBtn.disabled = (bookingCurrentPage >= maxPages);
      if (pageSlice.length === 0) {
        tbody.innerHTML = `<tr><td colspan="9" style="text-align:center;color:var(--text-muted);padding:30px;">No bookings found.</td></tr>`;
        return;
      }
      bookings.forEach(b => {
        const tr = document.createElement('tr');
        let statusBadge = `<span class="status-badge badge-reserved">Pending</span>`;
        if (b.booking_status === 'confirmed') statusBadge = `<span class="status-badge badge-occupied">Confirmed</span>`;
        else if (b.booking_status === 'checked_in') statusBadge = `<span class="status-badge badge-available">Checked In</span>`;
        else if (b.booking_status === 'checked_out') statusBadge = `<span class="status-badge badge-maintenance">Checked Out</span>`;
        else if (b.booking_status === 'cancelled') statusBadge = `<span class="status-badge badge-dirty">Cancelled</span>`;
        let actionBtns = '';
        if (b.booking_status === 'confirmed') {
          actionBtns = `<button class="btn-table-action" onclick="updateBookingStatus(${b.id}, 'checked_in', '${b.assigned_room_number || '101'}')">Check-In ➔</button>`;
        } else if (b.booking_status === 'checked_in') {
          actionBtns = `<button class="btn-table-action" onclick="updateBookingStatus(${b.id}, 'checked_out')">Check-Out ✓</button>`;
        } else {
          actionBtns = `<span style="font-size:0.75rem;color:var(--text-muted);">Completed</span>`;
        }
        tr.innerHTML = `
          <td><strong>${b.ref_number}</strong></td>
          <td>${b.guest_name}</td>
          <td style="font-size:0.8rem;">${b.guest_phone || '—'}</td>
          <td>${b.room_type_name}</td>
          <td>${b.check_in}</td>
          <td>${b.check_out} (${b.total_nights}n)</td>
          <td><strong>${b.assigned_room_number ? 'Room ' + b.assigned_room_number : 'Unassigned'}</strong></td>
          <td>${statusBadge}</td>
          <td>${actionBtns}</td>
        `;
        tbody.appendChild(tr);
      });
    }
    const handleBookingSearch = debounce(() => {
      const q = document.getElementById('bookingSearchInput').value.toLowerCase();
      const filtered = currentBookings.filter(b => 
        b.guest_name.toLowerCase().includes(q) ||
        b.ref_number.toLowerCase().includes(q) ||
        (b.guest_phone && b.guest_phone.toLowerCase().includes(q))
      );
      bookingCurrentPage = 1;
      renderBookings(filtered);
    }, 250);
    async function updateBookingStatus(id, status, roomNumber) {
      try {
        const res = await fetch(`/api/bookings/${id}/status`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ status, room_number: roomNumber })
        });
        if (res.ok) {
          const data = await res.json();
          if (data.success) {
            loadBookings();
            loadRooms();
            fetchStats();
            addActivityItem(`Booking updated to ${status.toUpperCase()}`);
            return;
          }
        }
        throw new Error('API fallback');
      } catch (err) {
        const state = getDemoState();
        const bk = state.bookings.find(b => b.id === id);
        if (bk) {
          bk.booking_status = status;
          saveDemoState(state);
          loadBookings();
          addActivityItem(`Booking ${bk.ref_number} updated to ${status.toUpperCase()} (Demo)`);
        }
      }
    }
    function openNewBookingModal() {
      const today = new Date().toISOString().split('T')[0];
      const tomorrow = new Date(Date.now() + 86400000).toISOString().split('T')[0];
      document.getElementById('nbCheckin').value = today;
      document.getElementById('nbCheckout').value = tomorrow;
      openModal('newBookingModal');
    }
    async function handleNewBookingSubmit(e) {
      e.preventDefault();
      const guest_name = document.getElementById('nbName').value.trim();
      const guest_phone = document.getElementById('nbPhone').value.trim();
      const guest_email = document.getElementById('nbEmail').value.trim();
      const room_type_id = document.getElementById('nbRoomType').value;
      const guests_count = parseInt(document.getElementById('nbGuests').value);
      const checkin_date = document.getElementById('nbCheckin').value;
      const checkout_date = document.getElementById('nbCheckout').value;
      const special_requests = document.getElementById('nbRequests').value;
      try {
        const res = await fetch('/api/bookings', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            guest_name, guest_phone, guest_email, room_type_id,
            guests_count, checkin_date, checkout_date,
            special_requests, source: 'walk_in'
          })
        });
        if (res.ok) {
          const data = await res.json();
          if (data.success) {
            closeModal('newBookingModal');
            document.getElementById('newBookingForm').reset();
            loadBookings();
            loadRooms();
            fetchStats();
            alert(`Walk-in booking created! Ref: ${data.ref_number} (Room: ${data.assigned_room || 'Pending'})`);
            addActivityItem(`Walk-in reservation confirmed for ${guest_name} (${data.ref_number})`);
            return;
          }
        }
        throw new Error('API fallback');
      } catch (err) {
        const state = getDemoState();
        const newRef = 'TS-' + Math.floor(100000 + Math.random() * 900000);
        const newBk = {
          id: Date.now(),
          ref_number: newRef,
          guest_name,
          guest_phone,
          guest_email,
          room_type_name: room_type_id === 'deluxe' ? 'Heritage Deluxe Room' : room_type_id === 'garden' ? 'Premium Garden View' : 'Grand Suite',
          check_in: checkin_date,
          check_out: checkout_date,
          total_nights: 1,
          num_guests: guests_count,
          total_amount: 3499,
          payment_status: 'paid',
          booking_status: 'confirmed',
          assigned_room_number: '106'
        };
        state.bookings.unshift(newBk);
        saveDemoState(state);
        closeModal('newBookingModal');
        document.getElementById('newBookingForm').reset();
        loadBookings();
        addActivityItem(`Walk-in reservation confirmed for ${guest_name} (${newRef})`);
        alert(`Walk-in booking created! Ref: ${newRef} (Room: 106)`);
      }
    }
    async function loadOrders() {
      try {
        const res = await fetch('/api/orders');
        if (res.ok) {
          const data = await res.json();
          if (data.success) {
            currentOrders = data.orders;
            renderOrders(currentOrders);
            return;
          }
        }
        throw new Error('API fallback');
      } catch (err) {
        const state = getDemoState();
        currentOrders = state.orders;
        renderOrders(currentOrders);
      }
    }
    function renderOrders(orders) {
      const colNew = document.getElementById('kotColNew');
      const colPrep = document.getElementById('kotColPreparing');
      const colReady = document.getElementById('kotColReady');
      const colDel = document.getElementById('kotColDelivered');
      colNew.innerHTML = ''; colPrep.innerHTML = ''; colReady.innerHTML = ''; colDel.innerHTML = '';
      let cNew = 0, cPrep = 0, cReady = 0, cDel = 0;
      orders.forEach(o => {
        const card = document.createElement('div');
        card.className = 'kot-card';
        let itemsHtml = o.items.map(it => `
          <div class="kot-item-row">
            <span><span class="kot-item-qty">${it.qty}x</span> ${it.name}</span>
            <span>₹${it.price * it.qty}</span>
          </div>
        `).join('');
        let actions = '';
        if (o.order_status === 'new') {
          cNew++;
          actions = `<button class="btn-primary" style="width:100%;font-size:0.75rem;" onclick="updateOrderStatus(${o.id}, 'preparing')">Start Cooking ➔</button>`;
          card.innerHTML = `
            <div class="kot-card-header">
              <span class="kot-source-badge">${o.source_type.toUpperCase()} ${o.source_number}</span>
              <span class="kot-time">${o.order_ref}</span>
            </div>
            <div class="kot-items-list">${itemsHtml}</div>
            ${o.notes ? `<div style="font-size:0.75rem;color:#b95d08;">Note: ${o.notes}</div>` : ''}
            <div class="kot-total-row"><span>Total:</span><span>₹${o.total}</span></div>
            <div class="kot-actions">${actions}</div>
          `;
          colNew.appendChild(card);
        } else if (o.order_status === 'preparing') {
          cPrep++;
          actions = `<button class="btn-primary" style="width:100%;background:#27ae60;font-size:0.75rem;" onclick="updateOrderStatus(${o.id}, 'ready')">Mark Ready ✓</button>`;
          card.innerHTML = `
            <div class="kot-card-header">
              <span class="kot-source-badge">${o.source_type.toUpperCase()} ${o.source_number}</span>
              <span class="kot-time">${o.order_ref}</span>
            </div>
            <div class="kot-items-list">${itemsHtml}</div>
            <div class="kot-total-row"><span>Total:</span><span>₹${o.total}</span></div>
            <div class="kot-actions">${actions}</div>
          `;
          colPrep.appendChild(card);
        } else if (o.order_status === 'ready') {
          cReady++;
          actions = `<button class="btn-primary" style="width:100%;background:var(--slate);font-size:0.75rem;" onclick="updateOrderStatus(${o.id}, 'delivered')">Mark Delivered ✓</button>`;
          card.innerHTML = `
            <div class="kot-card-header">
              <span class="kot-source-badge">${o.source_type.toUpperCase()} ${o.source_number}</span>
              <span class="kot-time">${o.order_ref}</span>
            </div>
            <div class="kot-items-list">${itemsHtml}</div>
            <div class="kot-total-row"><span>Total:</span><span>₹${o.total}</span></div>
            <div class="kot-actions">${actions}</div>
          `;
          colReady.appendChild(card);
        } else {
          cDel++;
          card.innerHTML = `
            <div class="kot-card-header">
              <span class="kot-source-badge">${o.source_type.toUpperCase()} ${o.source_number}</span>
              <span class="kot-time">Delivered</span>
            </div>
            <div class="kot-items-list">${itemsHtml}</div>
            <div class="kot-total-row"><span>Paid Total:</span><span>₹${o.total}</span></div>
          `;
          colDel.appendChild(card);
        }
      });
      document.getElementById('countKotNew').textContent = cNew;
      document.getElementById('countKotPreparing').textContent = cPrep;
      document.getElementById('countKotReady').textContent = cReady;
      document.getElementById('countKotDelivered').textContent = cDel;
    }
    async function updateOrderStatus(id, status) {
      try {
        const res = await fetch(`/api/orders/${id}/status`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ status })
        });
        if (res.ok) {
          const data = await res.json();
          if (data.success) {
            loadOrders();
            fetchStats();
            return;
          }
        }
        throw new Error('API fallback');
      } catch (err) {
        const state = getDemoState();
        const ord = state.orders.find(o => o.id === id);
        if (ord) {
          ord.order_status = status;
          saveDemoState(state);
          renderOrders(state.orders);
          addActivityItem(`Order ${ord.order_ref} moved to ${status.toUpperCase()} (Demo)`);
        }
      }
    }
    async function loadConcierge() {
      try {
        const res = await fetch('/api/concierge');
        if (res.ok) {
          const data = await res.json();
          if (data.success) {
            currentConcierge = data.requests;
            renderConcierge(currentConcierge);
            return;
          }
        }
        throw new Error('API fallback');
      } catch (err) {
        const state = getDemoState();
        currentConcierge = state.concierge;
        renderConcierge(currentConcierge);
      }
    }
    function renderConcierge(requests) {
      const tbody = document.getElementById('conciergeTableBody');
      tbody.innerHTML = '';
      if (requests.length === 0) {
        tbody.innerHTML = `<tr><td colspan="9" style="text-align:center;color:var(--text-muted);padding:30px;">No service requests logged.</td></tr>`;
        return;
      }
      requests.forEach(r => {
        const tr = document.createElement('tr');
        let statusBadge = `<span class="status-badge badge-reserved">Pending</span>`;
        if (r.status === 'in_progress') statusBadge = `<span class="status-badge badge-dirty">In Progress</span>`;
        else if (r.status === 'resolved') statusBadge = `<span class="status-badge badge-available">Resolved</span>`;
        let prioBadge = r.priority === 'urgent' ? `<span style="color:#c0392b;font-weight:800;">🔴 URGENT</span>` : `Normal`;
        let actionBtn = '';
        if (r.status === 'pending') {
          actionBtn = `<button class="btn-primary" style="padding:4px 8px;font-size:0.75rem;" onclick="updateConciergeStatus(${r.id}, 'in_progress', 'Housekeeping')">Accept</button>`;
        } else if (r.status === 'in_progress') {
          actionBtn = `<button class="btn-primary" style="background:#27ae60;padding:4px 8px;font-size:0.75rem;" onclick="updateConciergeStatus(${r.id}, 'resolved')">Resolve ✓</button>`;
        }
        tr.innerHTML = `
          <td>#${r.id}</td>
          <td><strong style="font-size:1.1rem;color:var(--green-dark);">Room ${r.room_number}</strong></td>
          <td style="text-transform:capitalize;font-weight:600;">${r.request_type.replace('_', ' ')}</td>
          <td>${r.details || '—'}</td>
          <td>${prioBadge}</td>
          <td>${statusBadge}</td>
          <td>${r.assigned_to || 'Unassigned'}</td>
          <td style="font-size:0.75rem;color:var(--text-muted);">${r.created_at || 'Just now'}</td>
          <td>${actionBtn}</td>
        `;
        tbody.appendChild(tr);
      });
    }
    async function updateConciergeStatus(id, status, assigned) {
      try {
        const res = await fetch(`/api/concierge/${id}/status`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ status, assigned_to: assigned })
        });
        if (res.ok) {
          const data = await res.json();
          if (data.success) {
            loadConcierge();
            fetchStats();
            return;
          }
        }
        throw new Error('API fallback');
      } catch (err) {
        const state = getDemoState();
        const ticket = state.concierge.find(c => c.id === id);
        if (ticket) {
          ticket.status = status;
          if (assigned) ticket.assigned_to = assigned;
          saveDemoState(state);
          renderConcierge(state.concierge);
          addActivityItem(`Concierge Request #${id} marked ${status.toUpperCase()} (Demo)`);
        }
      }
    }
    async function loadReviews() {
      try {
        const res = await fetch('/api/reviews');
        if (res.ok) {
          const data = await res.json();
          if (data.success) {
            currentReviews = data.reviews;
            renderReviews(currentReviews);
            return;
          }
        }
        throw new Error('API fallback');
      } catch (err) {
        const state = getDemoState();
        currentReviews = state.reviews;
        renderReviews(currentReviews);
      }
    }
    function renderReviews(reviews) {
      const tbody = document.getElementById('reviewsTableBody');
      tbody.innerHTML = '';
      reviews.forEach(r => {
        const tr = document.createElement('tr');
        const stars = '★'.repeat(r.rating || 5) + '☆'.repeat(5 - (r.rating || 5));
        tr.innerHTML = `
          <td><strong>${r.guest_name}</strong></td>
          <td>${r.room_type || 'Guest Stay'}</td>
          <td style="color:var(--gold);font-size:1rem;letter-spacing:1px;">${stars}</td>
          <td style="font-size:0.75rem;color:var(--text-muted);">
            Clean: 5/5 • Food: 5/5 • Staff: 5/5
          </td>
          <td>"${r.comment || r.review_text || 'Excellent service!'}"</td>
          <td style="font-size:0.75rem;color:var(--text-muted);">${r.created_at || 'Recent'}</td>
          <td>
            <label style="display:flex;align-items:center;gap:6px;cursor:pointer;">
              <input type="checkbox" ${r.is_featured ? 'checked' : ''} onchange="toggleReviewFeatured(${r.id}, this.checked)">
              <span style="font-size:0.8rem;font-weight:600;">Featured</span>
            </label>
          </td>
        `;
        tbody.appendChild(tr);
      });
    }
    async function toggleReviewFeatured(id, isFeatured) {
      try {
        await fetch(`/api/reviews/${id}/feature`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ is_featured: isFeatured })
        });
      } catch (err) {
        const state = getDemoState();
        const rev = state.reviews.find(r => r.id === id);
        if (rev) {
          rev.is_featured = isFeatured ? 1 : 0;
          saveDemoState(state);
        }
      }
    }
    function populateQRSelect() {
      const type = document.getElementById('qrTypeSelect').value;
      const numSelect = document.getElementById('qrNumberSelect');
      numSelect.innerHTML = '';
      if (type === 'table') {
        for (let i = 1; i <= 14; i++) {
          const opt = document.createElement('option');
          opt.value = i;
          opt.textContent = `Table ${i}`;
          if (i === 7) opt.selected = true;
          numSelect.appendChild(opt);
        }
      } else {
        const roomNumbers = [
          '101','102','103','104','105','106','107','108','109','110','111','112',
          '201','202','203','204','205','206','207','208','209','210','211','212'
        ];
        roomNumbers.forEach((r, idx) => {
          const opt = document.createElement('option');
          opt.value = r;
          opt.textContent = `Room ${r}`;
          if (r === '204') opt.selected = true;
          numSelect.appendChild(opt);
        });
      }
    }
    function handleQRTypeChange() {
      populateQRSelect();
      generateStandeePreview();
    }
    function generateStandeePreview() {
      const type = document.getElementById('qrTypeSelect').value;
      const num = document.getElementById('qrNumberSelect').value;
      const cta = document.getElementById('qrCtaInput').value;
      const badge = document.getElementById('standeeTargetBadge');
      badge.textContent = type === 'table' ? `Table ${num}` : `Room ${num}`;
      document.getElementById('standeeCtaText').textContent = cta;
      const origin = (window.location.protocol === 'https:' || window.location.host.includes('tapstay.in')) 
        ? 'https://' + window.location.host 
        : window.location.origin;
      let targetUrl = '';
      if (type === 'table') {
        targetUrl = `${origin}/order.html?table=${num}`;
      } else {
        targetUrl = `${origin}/concierge.html?room=${num}`;
      }
      const qrContainer = document.getElementById('standeeQrContainer');
      qrContainer.innerHTML = '';
      if (typeof QRCode !== 'undefined') {
        new QRCode(qrContainer, {
          text: targetUrl,
          width: 160,
          height: 160,
          colorDark: "#1B4332",
          colorLight: "#FFFFFF",
          correctLevel: QRCode.CorrectLevel.M
        });
      }
    }
    function addActivityItem(text) {
      const feed = document.getElementById('liveActivityFeed');
      const item = document.createElement('div');
      item.style.cssText = 'padding:10px;background:#F8F9FA;border-radius:8px;border-left:3px solid var(--gold);animation:slideIn 0.3s;';
      const timeStr = new Date().toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
      item.innerHTML = `
        <div style="font-weight:700;">${text}</div>
        <div style="font-size:0.72rem;color:var(--text-muted);">${timeStr}</div>
      `;
      feed.insertBefore(item, feed.firstChild);
    }
    function startPolling() {
      if (pollingIntervalId) clearInterval(pollingIntervalId);
      pollingIntervalId = setInterval(() => {
        fetchStats();
        if (document.getElementById('tabBookings').classList.contains('active')) {
          loadBookings();
        }
        if (document.getElementById('tabKitchen').classList.contains('active')) {
          loadOrders();
        }
        if (document.getElementById('tabConcierge').classList.contains('active')) {
          loadConcierge();
        }
      }, 4000);
    }
    fetchStats();
    loadRooms();
    loadBookings();
    loadOrders();
    loadConcierge();
    loadReviews();
    startPolling();